// Package topology models the declared system topology an integration
// system's host emits. The record declares the system's shape: its components
// (blocks) and the wiring between them, expressed inline on each component —
// the topics it subscribes to and publishes on, the API contracts it provides
// and consumes, and the external ports it uses. Top-level topics[] and
// ports[] sections carry the shared metadata (contracts, external systems)
// those inline references point at.
//
// The record carries only minted facts: the Dapr binding a port deploys as
// (its spec.type, address, credentials) is environment-owned deployment
// configuration in the GitOps repo, and an extractor's cadence is its CronJob
// there. Neither appears here.
//
// The CLI never derives a topology itself: the system host's `graph` verb
// prints the record — JSON only, on stdout — and consumers decode that stream.
package topology

import (
	"encoding/json"
	"fmt"
	"io"
)

const (
	// APIVersion is the topology schema this CLI understands. A record with
	// any other apiVersion is an error, not a guess.
	APIVersion = "topology.intropy.io/v1"

	// Kind is the expected document kind under APIVersion.
	Kind = "SystemTopology"
)

// Topology is one system's declared graph. Wiring is inlined on each component
// rather than kept in a separate edge list: a component names the topics it
// subscribes to and publishes on and the ports it uses. The top-level Topics
// and Ports sections are lookup tables the inline references resolve against
// (contract, external system).
type Topology struct {
	APIVersion string      `json:"apiVersion"`
	Kind       string      `json:"kind,omitempty"`
	System     string      `json:"system"`
	Components []Component `json:"components,omitempty"`
	Topics     []Topic     `json:"topics,omitempty"`
	Ports      []Port      `json:"ports,omitempty"`
	Contracts  []Contract  `json:"contracts,omitempty"`
	// APIs, and each component's Provides/Consumes below, are the contract
	// (request/response) surfaces. Their element shape is not yet finalized,
	// so they are parsed opaquely: preserved for round-tripping to the
	// frontend without asserting a schema the CLI does not yet render.
	APIs []json.RawMessage `json:"apis,omitempty"`
}

// Component is a deployable block of the system. Kind is the block type
// (extractor, loader, transactional-integration, …). A component's directory,
// which joins it to its .intropy/scaffold.json project, is its Name relative
// to the system root.
type Component struct {
	Name       string         `json:"name"`
	Kind       string         `json:"kind"`
	Subscribes []TopicRef     `json:"subscribes,omitempty"`
	Publishes  []Publication  `json:"publishes,omitempty"`
	Ports      []PortUse      `json:"ports,omitempty"`
	// Provides/Consumes are contract surfaces, parsed opaquely (see APIs).
	Provides []json.RawMessage `json:"provides,omitempty"`
	Consumes []json.RawMessage `json:"consumes,omitempty"`
}

// TopicRef is a component's subscription to a pub/sub topic.
type TopicRef struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// Publication is a component's output onto a pub/sub topic.
type Publication struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// PortUse is a component's use of an external port. Direction is "in"
// (external → component) or "out" (component → external).
type PortUse struct {
	Port      string `json:"port"`
	Direction string `json:"direction"`
}

// Topic is a declared pub/sub topic: the metadata for a (PubSub, Topic) pair
// components reference. Contract is the message contract it carries;
// Publishers/Subscribers name the components on each end.
type Topic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Contract is a message contract in the system's registry, keyed by Name —
// the same fully-qualified type name Topic.Contract references. ShortName is
// the bare type name (the join key to a scaffold record's values.contract).
// Schema is the contract's JSON Schema as the host emitted it; the CLI passes
// it through to the frontend without interpreting it. Fingerprint identifies
// the schema shape (a hash over its canonical form), so equal fingerprints
// mean equal shapes across systems.
type Contract struct {
	Name        string          `json:"name"`
	Kind        string          `json:"kind,omitempty"`
	ShortName   string          `json:"shortName,omitempty"`
	MediaType   string          `json:"mediaType,omitempty"`
	Fingerprint string          `json:"fingerprint,omitempty"`
	Schema      json.RawMessage `json:"schema,omitempty"`
}

// Port is an external system integration point. The name is its whole
// identity — the deployed Dapr binding type, address, and credentials are
// environment-owned deployment configuration, never part of the record.
// ExternalSystem is the system it fronts, Directions the directions it is
// wired in, and UsedBy the components that use it.
type Port struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	UsedBy         []string `json:"usedBy,omitempty"`
}

// Entry is one system's topology plus the workspace directory it belongs to,
// flattened into one self-describing JSON document for the API.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// Decode parses a topology record from r (typically a host `graph` verb's
// stdout). A record whose apiVersion this CLI does not understand is an
// error, not a guess. Callers wrap the error with the record's origin.
func Decode(r io.Reader) (*Topology, error) {
	var t Topology
	if err := json.NewDecoder(r).Decode(&t); err != nil {
		return nil, fmt.Errorf("parse topology record: %w", err)
	}
	if t.APIVersion != APIVersion {
		return nil, fmt.Errorf("unsupported topology apiVersion %q (this CLI understands %q)",
			t.APIVersion, APIVersion)
	}
	return &t, nil
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  api,
  type CreateResponse,
  type TemplateDetail,
  type TemplateList,
  type TemplateSummary,
} from '../api'
import { Combobox } from './Combobox'
import { Field, FormField, isEmpty } from './form'

/** The three create placeholders on the flow canvas, one per archetype
 *  column: in → process → out. */
export type SlotKind = 'extractor' | 'transactional' | 'loader'

// The intropy.dev/block-kind label value each slot filters templates by.
const KIND_BLOCK_LABEL: Record<SlotKind, string> = {
  extractor: 'extractor',
  transactional: 'transactional-integration',
  loader: 'loader',
}

const KIND_TITLE: Record<SlotKind, string> = {
  extractor: 'extractor',
  transactional: 'core block',
  loader: 'loader',
}

type CreateState =
  | { phase: 'idle' }
  | { phase: 'running' }
  | { phase: 'error'; message: string; status: number }

// norm compares label values the way dataFlowFor compares kinds: ignoring
// case and hyphens, so "transactional-integration" matches however the
// library spells it.
const norm = (s: string) => s.toLowerCase().replace(/-/g, '')

interface Props {
  kind: SlotKind
  /** Root-relative directory the new block scaffolds into ("." = workspace root). */
  systemPath: string
  systemLabel: string
  onClose: () => void
  /** Called with the created scaffold's root-relative path — the caller
   *  refreshes /api/flow so the new block appears as a ghost node. */
  onCreated: (outputDir: string) => void
}

// CreateDrawer is the flow view's create surface: opened by a placeholder
// slot, it offers the library's templates for that block kind and renders the
// selected one's manifest as the same form the templates view uses, scoped to
// the slot's system. Success is reported to the caller — the drawer closes
// and the canvas shows the new scaffold as a ghost node.
export function CreateDrawer({ kind, systemPath, systemLabel, onClose, onCreated }: Props) {
  const [list, setList] = useState<TemplateList | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  const [showAll, setShowAll] = useState(false)
  const [tpl, setTpl] = useState<string | null>(null)

  useEffect(() => {
    api
      .listTemplates()
      .then(setList)
      .catch((e: unknown) => setListError(errText(e)))
  }, [])

  const candidates = useMemo<TemplateSummary[]>(() => {
    if (!list) return []
    const entries: TemplateSummary[] =
      list.entries ?? list.templates.map((name) => ({ name }))
    if (showAll) return entries
    const want = norm(KIND_BLOCK_LABEL[kind])
    return entries.filter((e) => norm(e.labels?.['intropy.dev/block-kind'] ?? '') === want)
  }, [list, showAll, kind])

  // Keep the selection valid as the candidate list settles (load, show-all).
  useEffect(() => {
    setTpl((cur) =>
      cur && candidates.some((c) => c.name === cur) ? cur : candidates[0]?.name ?? null,
    )
  }, [candidates])

  return (
    <aside className="create-drawer">
      <header className="create-drawer-head">
        <div>
          <h2 className="create-drawer-title">New {KIND_TITLE[kind]}</h2>
          <span className="create-drawer-sys">in {systemLabel}</span>
        </div>
        <button type="button" className="flow-detail-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </header>

      {listError && <div className="banner error">{listError}</div>}
      {!list && !listError && <div className="empty">loading templates…</div>}

      {list && candidates.length === 0 && (
        <div className="empty">
          no template in {list.owner}/{list.repo}@{list.version} carries{' '}
          <code>intropy.dev/block-kind: {KIND_BLOCK_LABEL[kind]}</code>
          <div>
            <button type="button" className="flow-refresh" onClick={() => setShowAll(true)}>
              show all templates
            </button>
          </div>
        </div>
      )}

      {list && candidates.length > 0 && (
        <>
          <Field label="template" required>
            <Combobox
              value={tpl}
              options={candidates.map((c) => ({
                value: c.name,
                label: c.title ? `${c.title} (${c.name})` : c.name,
              }))}
              onChange={setTpl}
              placeholder="Select a template…"
            />
          </Field>
          {!showAll && (
            <button
              type="button"
              className="drawer-show-all"
              onClick={() => setShowAll(true)}
            >
              show all templates
            </button>
          )}
          {tpl && (
            <DrawerForm
              key={tpl}
              template={tpl}
              systemPath={systemPath}
              onCreated={onCreated}
            />
          )}
        </>
      )}
    </aside>
  )
}

// DrawerForm mirrors the templates view's TemplatePanel: manifest fetched,
// defaults seeded, required fields tracked, force offered on a 409. It is
// keyed by template name so switching templates resets all form state. The
// differences: the output directory is locked under the slot's system, and
// success closes the drawer instead of rendering a result card.
function DrawerForm({
  template,
  systemPath,
  onCreated,
}: {
  template: string
  systemPath: string
  onCreated: Props['onCreated']
}) {
  const [detail, setDetail] = useState<TemplateDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [values, setValues] = useState<Record<string, unknown>>({})
  const [intName, setIntName] = useState('')
  const [force, setForce] = useState(false)
  const [create, setCreate] = useState<CreateState>({ phase: 'idle' })

  useEffect(() => {
    api
      .getTemplate(template)
      .then((d) => {
        setDetail(d)
        // Prefill declared defaults so the form shows what a bare run would use.
        const seeded: Record<string, unknown> = {}
        for (const f of d.fields) {
          if (f.default !== undefined) seeded[f.name] = f.default
        }
        setValues(seeded)
      })
      .catch((e: unknown) => setError(errText(e)))
  }, [template])

  const setValue = useCallback((key: string, v: unknown) => {
    setValues((prev) => ({ ...prev, [key]: v }))
  }, [])

  const missing = useMemo(() => {
    if (!detail) return []
    return detail.fields
      .filter((f) => f.required && isEmpty(values[f.name]))
      .map((f) => f.name)
  }, [detail, values])

  const run = useCallback(() => {
    setCreate({ phase: 'running' })
    api
      .createTemplate(template, { name: intName, dir: systemPath, values, force })
      .then((result: CreateResponse) => onCreated(result.outputDir))
      .catch((e: unknown) => {
        const err = e as { message?: string; status?: number }
        setCreate({ phase: 'error', message: errText(e), status: err.status ?? 0 })
      })
  }, [template, intName, systemPath, values, force, onCreated])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!detail) {
    return <div className="empty">loading {template}…</div>
  }

  const canRun = intName.trim() !== '' && missing.length === 0 && create.phase !== 'running'
  const prefix = systemPath === '.' ? '' : `${systemPath}/`

  return (
    <form
      className="template-form"
      onSubmit={(e) => {
        e.preventDefault()
        if (canRun) run()
      }}
    >
      {detail.description && <p className="template-desc">{detail.description}</p>}

      <Field
        label="out-dir"
        title="Output directory"
        description={
          prefix
            ? 'Scaffolded inside the system directory'
            : 'Scaffolded under the workspace root'
        }
        required
      >
        <div className="drawer-dir">
          {prefix && <span className="drawer-dir-prefix">{prefix}</span>}
          <input
            type="text"
            value={intName}
            onChange={(e) => setIntName(e.target.value)}
            placeholder="my-integration"
            autoFocus
          />
        </div>
      </Field>

      {detail.fields.map((f) => (
        <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
      ))}

      {missing.length > 0 && (
        <div className="form-hint">missing required: {missing.join(', ')}</div>
      )}

      {create.phase === 'error' && create.status === 409 && (
        <label className="force-row">
          <input type="checkbox" checked={force} onChange={(e) => setForce(e.target.checked)} />
          render into the non-empty directory anyway
        </label>
      )}

      <div className="form-actions">
        <button type="submit" className="run-btn" disabled={!canRun}>
          {create.phase === 'running' ? 'creating…' : 'int create'}
        </button>
      </div>

      {create.phase === 'error' && <div className="banner error">{create.message}</div>}
    </form>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

package dashboard

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
// the detail endpoint returns, so a huge file cannot bloat a response.
const maxDocBytes = 128 * 1024

// providers are the request-independent sources the API reads beyond the
// workspace's own files: what a system host declares about its topology, and
// what the GitOps repository says is deployed. Both run a command, so both are
// injected as function values that tests replace. templates is a value, not a
// function: it carries configuration (release pin, test overrides), not a
// stubbed behavior — tests override its fields instead.
type providers struct {
	topology  topologyProvider
	deploy    deployProvider
	templates templatesProvider
}

// deployStateTimeout bounds one deploy status run.
//
// It exists for the checkout lock rather than for the browser: the command holds
// an exclusive lock on the shared GitOps checkout for its whole duration, and an
// ArgoCD server that accepts connections but never answers would otherwise keep
// that lock — blocking the user's own intropy deploy indefinitely. A minute is
// generous for a fetch plus a handful of ArgoCD calls and short enough that a
// hung one lets go.
const deployStateTimeout = time.Minute

// apiServer holds the request-independent state for the JSON API.
type apiServer struct {
	root      string
	version   string
	topo      topologyProvider
	dep       deployProvider
	templates templatesProvider

	// createMu serializes template create runs: two concurrent renders of the
	// same name would race on the output directory, and each run downloads a
	// library tarball. The same bargain depMu makes for the shared checkout.
	createMu sync.Mutex

	// topoMu guards the cached provider result. Fetching runs the hosts'
	// graph verbs (a dotnet build on first run), so the result is computed
	// once — on the first /api/topology request — and reused until an
	// explicit refresh.
	topoMu      sync.Mutex
	topoLoaded  bool
	topoWarming bool
	topoEntries []topology.Entry
	topoErrs    []string

	// depMu guards the cached deployment state, keyed by root-relative path.
	// Reading it refreshes a shared GitOps checkout under an exclusive lock, so
	// unlike the topology this is cached per integration and computed only for
	// the ones actually asked about.
	depMu     sync.Mutex
	depStates map[string]deployState
}

// topologyReport is the /api/topology payload: every declared topology plus
// the per-host failures the UI renders. Topologies is always an array (never
// null) even when empty.
type topologyReport struct {
	Topologies []topologyEntry `json:"topologies"`
	Errors     []string        `json:"errors,omitempty"`
}

// topologyEntry is one system's declared topology plus the authored
// enrichment read from its directory: message descriptions keyed by port
// name. The docs ride beside the Topology rather than inside it — the
// topology stays exactly what the host declared.
type topologyEntry struct {
	topology.Entry
	MessageDocs map[string]messageDoc `json:"messageDocs,omitempty"`
}

// fileDoc is a text document surfaced in an integration's detail view.
type fileDoc struct {
	Name    string `json:"name"`
	Content string `json:"content"`
}

// integrationSummary is a scaffold entry plus the coordinates the sidebar
// tree groups by: Name is the directory that carries the .intropy record.
// System is the name a sibling system-host scaffold declares for the
// directory's parent, falling back to the parent folder's name; Domain is the
// system's parent folder. Absent a host, System is empty when the integration
// sits directly under the workspace root, and Domain is empty when the
// system does.
type integrationSummary struct {
	template.ScaffoldEntry
	Name   string `json:"name"`
	System string `json:"system,omitempty"`
	Domain string `json:"domain,omitempty"`
	// SystemPath is the root-relative directory of the system the integration
	// belongs to ("." when the system is rooted at the workspace itself).
	// Unlike System — a declared name two directories can share — it is a
	// unique grouping key, and it matches the `path` of the topology record
	// the system's host produces. Absent when the integration has no system.
	SystemPath string `json:"systemPath,omitempty"`
}

// integrationDetail is a single integration plus best-effort, on-disk
// enrichment. Every enrichment field is optional and absent when the
// corresponding file or directory does not exist.
type integrationDetail struct {
	integrationSummary
	Agents        *fileDoc        `json:"agents,omitempty"`
	Readme        *fileDoc        `json:"readme,omitempty"`
	Components    []DaprComponent `json:"components,omitempty"`
	PipelineSteps []string        `json:"pipelineSteps,omitempty"`
}

// newHandler wires the API routes and the SPA static handler onto a mux.
func newHandler(root, version string, p providers) (http.Handler, error) {
	api := &apiServer{root: root, version: version, topo: p.topology, dep: p.deploy, templates: p.templates}
	static, err := staticHandler()
	if err != nil {
		return nil, err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", api.health)
	mux.HandleFunc("GET /api/integrations", api.listIntegrations)
	mux.HandleFunc("GET /api/systems", api.listSystems)
	// GET lists what is declared; POST re-assembles one system's host
	// (sys update, or sys create when the directory has none).
	mux.HandleFunc("POST /api/systems/{path...}", api.syncSystem)
	mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
	mux.HandleFunc("GET /api/catalog/{path...}", api.catalog)
	mux.HandleFunc("GET /api/flow", api.flow)
	mux.HandleFunc("GET /api/topology", api.topologies)
	mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
	// The verb carries the meaning rather than a /refresh segment: a {path...}
	// wildcard has to be the last thing in the pattern. GET serves what has
	// already been read, POST runs the command again.
	mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
	mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
	// Template endpoints follow the same GET-read / POST-act split: list and
	// show fetch the library release, create renders into the workspace.
	mux.HandleFunc("GET /api/templates", api.listTemplates)
	mux.HandleFunc("GET /api/templates/{name}", api.getTemplate)
	mux.HandleFunc("POST /api/templates/{name}/create", api.createTemplate)
	mux.Handle("/", static)
	return mux, nil
}

func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{
		"status":    "ok",
		"version":   s.version,
		"workspace": s.workspaceName(),
	})
}

// workspaceName is the served root's directory name — the label the flow
// view gives the workspace pseudo-system, so a dashboard on ~/dev/acme says
// "acme" rather than a generic "Workspace". Serve hands the handler an
// absolute root; the extra Abs covers callers (tests) that pass a relative
// one, where Base would otherwise answer ".".
func (s *apiServer) workspaceName() string {
	root := s.root
	if abs, err := filepath.Abs(root); err == nil {
		root = abs
	}
	return filepath.Base(root)
}

// listIntegrations mirrors `int list -o json` — the same scaffold entries in
// the same order — with the derived name/system fields added on top and each
// Path normalized to a root-relative identifier. The response is always an
// array (never null) even when empty.
func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	summaries := make([]integrationSummary, 0, len(entries))
	for _, e := range entries {
		summaries = append(summaries, s.summarize(e, systems))
	}
	writeJSON(w, http.StatusOK, summaries)
}

// systemInfo is one declared system: the directory holding a system-host
// scaffold, root-relative, plus the name the host declares.
type systemInfo struct {
	Path string `json:"path"`
	Name string `json:"name"`
}

// listSystems reports every declared system, so the flow view can offer a
// system that has a host but no blocks yet — /api/flow only carries systems
// through the blocks that belong to them. The response is always an array
// (never null) even when empty.
func (s *apiServer) listSystems(w http.ResponseWriter, _ *http.Request) {
	_, systems := s.scan()
	out := make([]systemInfo, 0, len(systems))
	for dir, name := range systems {
		out = append(out, systemInfo{Path: s.relPath(dir), Name: name})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	writeJSON(w, http.StatusOK, out)
}

// scan splits the workspace's scaffold entries for the API: the integration
// blocks to catalog, plus the declared systems keyed by their root directory
// (the directory holding a system-host scaffold). Support projects — the host
// and its shared contracts library — are infrastructure the system view
// already represents, not integrations to list.
func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
	entries, _ := template.ListScaffolds(s.root)
	systems = map[string]string{}
	for _, e := range entries {
		if e.Role == template.RoleSystemHost {
			systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
		}
	}
	blocks = entries[:0]
	for _, e := range entries {
		if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
			continue
		}
		blocks = append(blocks, e)
	}
	return blocks, systems
}

// systemName is the name a system-host scaffold declares for its system
// (the template's `name` value, recorded at `sys create`), falling back to
// the host's parent directory name.
func systemName(host template.ScaffoldEntry) string {
	if name, ok := host.Values["name"].(string); ok && name != "" {
		return name
	}
	dir := filepath.Dir(host.Path)
	if abs, err := filepath.Abs(dir); err == nil {
		dir = abs
	}
	return filepath.Base(dir)
}

// summarize derives an entry's tree coordinates from its path and the
// declared systems. A sibling system-host makes membership explicit: its
// declared name wins over the folder-derived one and applies even directly
// under the workspace root (where no folder-derived system exists).
// Otherwise the workspace root itself never counts as a system or domain, so
// an integration scaffolded at the root has neither and one directly under
// the root has a system but no domain. The served Path is made root-relative
// so it is a stable, URL-safe identifier regardless of whether the command
// was given a relative or absolute root (an absolute path would otherwise
// break detail lookups).
func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
	sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
	sum.Path = s.relPath(e.Path)
	path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
	parent := filepath.Dir(path)
	if declared, ok := systems[parent]; ok && path != root {
		sum.System = declared
		sum.SystemPath = s.relPath(parent)
		if grand := filepath.Dir(parent); parent != root && grand != root {
			sum.Domain = filepath.Base(grand)
		}
		return sum
	}
	if path == root || parent == root {
		return sum
	}
	sum.System = filepath.Base(parent)
	sum.SystemPath = s.relPath(parent)
	if grand := filepath.Dir(parent); grand != root {
		sum.Domain = filepath.Base(grand)
	}
	return sum
}

// relPath turns an entry's on-disk path into the root-relative, slash-separated
// identifier used in API responses and URLs. It falls back to the cleaned path
// so a value is always produced even if Rel fails (e.g. differing volumes).
func (s *apiServer) relPath(p string) string {
	if rel, err := filepath.Rel(s.root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

// flow returns every integration enriched with the pipeline steps and Dapr
// components the flow canvas draws, so the whole graph loads in one request.
// It reuses integrationDetail but leaves the document fields (agents/readme)
// nil — the canvas nodes do not render them.
func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	nodes := make([]integrationDetail, 0, len(entries))
	for _, e := range entries {
		dir := e.Path
		nodes = append(nodes, integrationDetail{
			integrationSummary: s.summarize(e, systems),
			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
		})
	}
	writeJSON(w, http.StatusOK, nodes)
}

// topologies returns every system topology declared by a host's graph verb,
// each Path normalized to the same root-relative identifier integration
// paths use, so the flow canvas can match a topology to the integrations
// living beside its host. The provider result is cached after the first
// request (the verb builds the host); POST /api/topology/refresh recomputes.
func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
}

// refreshTopologies recomputes the topology cache by re-running every host's
// graph verb, then returns the fresh report.
func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
}

// topologyReport assembles the /api/topology payload: the cached provider
// result plus the message docs read fresh from disk on every request, so an
// edited doc shows up on a browser refresh without re-running the hosts'
// graph verbs.
func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
	entries, errs := s.cachedTopologies(ctx, force)
	report := topologyReport{
		Topologies: make([]topologyEntry, 0, len(entries)),
		Errors:     append([]string(nil), errs...),
	}
	for _, e := range entries {
		docs, docErrs := s.messageDocs(e)
		report.Topologies = append(report.Topologies, topologyEntry{Entry: e, MessageDocs: docs})
		report.Errors = append(report.Errors, docErrs...)
	}
	return report
}

// cachedTopologies returns the provider result — computed on first use or
// when force is set, reused otherwise. Concurrent requests share one
// computation. Entry paths are normalized to root-relative identifiers.
func (s *apiServer) cachedTopologies(ctx context.Context, force bool) ([]topology.Entry, []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	if !s.topoLoaded || force {
		entries, errs := s.topo(ctx)
		s.topoEntries = make([]topology.Entry, 0, len(entries))
		for _, e := range entries {
			e.Path = s.relPath(e.Path)
			s.topoEntries = append(s.topoEntries, e)
		}
		s.topoErrs, s.topoLoaded = errs, true
	}
	return s.topoEntries, s.topoErrs
}

// topologiesLoaded reports whether the topology cache has been computed, and
// serves the cached result if it has. It never blocks on the computation:
// computing runs every host's graph verb (a dotnet build on first run) under
// one mutex, and the catalog endpoint must answer promptly rather than queue
// behind that. Instead the caller asks warmTopologies to compute in the
// background, so the pending answer becomes a matched one on the next fetch
// without anyone visiting the flow view first.
func (s *apiServer) topologiesLoaded() (loaded bool, entries []topology.Entry, errs []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	return s.topoLoaded, s.topoEntries, s.topoErrs
}

// warmTopologies triggers the topology computation in the background when the
// cache is cold. Only one warm-up runs at a time — cachedTopologies
// serialises on topoMu, and warming guards against stacking requests behind
// it. A detached context keeps the hosts' graph verbs running after the
// request that prompted them has been answered.
func (s *apiServer) warmTopologies() {
	s.topoMu.Lock()
	if s.topoLoaded || s.topoWarming {
		s.topoMu.Unlock()
		return
	}
	s.topoWarming = true
	s.topoMu.Unlock()

	go func() {
		defer func() {
			s.topoMu.Lock()
			s.topoWarming = false
			s.topoMu.Unlock()
		}()
		// The catalog requests that triggered this are already answered; the
		// computation is for the next one.
		_, _ = s.cachedTopologies(context.Background(), false)
	}()
}

// messageDocs reads the authored port payload descriptions beside a system,
// keyed by port name. A doc naming a port the topology does not declare is
// surfaced as an error and withheld — never guessed around. Error messages
// carry the doc's workspace-relative path.
func (s *apiServer) messageDocs(e topology.Entry) (map[string]messageDoc, []string) {
	docs, errs := readMessageDocs(filepath.Join(s.root, filepath.FromSlash(e.Path)))
	prefix := ""
	if e.Path != "." {
		prefix = e.Path + "/"
	}
	for i, msg := range errs {
		errs[i] = prefix + msg
	}
	known := map[string]bool{}
	for _, c := range e.Ports {
		known[c.Name] = true
	}
	var unknown []string
	for name := range docs {
		if !known[name] {
			unknown = append(unknown, name)
			delete(docs, name)
		}
	}
	sort.Strings(unknown)
	for _, name := range unknown {
		errs = append(errs, fmt.Sprintf("%s%s/%s.md: no port %q declared by system %q",
			prefix, messagesDirName, name, name, e.System))
	}
	if len(docs) == 0 {
		docs = nil
	}
	return docs, errs
}

func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.enrich(e, systems)
	})
}

// getDeployState serves what the deploy status command last said about one
// integration, running it on the first request and reusing that until a POST to
// the same path. It is a separate endpoint from the integration detail because
// the two cost very different things: detail is local files, this refreshes a
// GitOps checkout over the network. Keeping them apart lets the detail panel
// render immediately and fill the deployment in when it arrives.
func (s *apiServer) getDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, false)
}

// refreshDeployState re-runs the command for one integration and returns the
// fresh result, picking up a deploy someone just made from another terminal.
func (s *apiServer) refreshDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, true)
}

func (s *apiServer) deployStateByPath(w http.ResponseWriter, r *http.Request, force bool) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.cachedDeployState(r.Context(), s.summarize(e, systems), force)
	})
}

// byPath resolves the {path...} wildcard to a scaffolded integration and serves
// what render makes of it, or 404s. Shared so the detail and deployment
// endpoints agree about which identifiers name the same integration.
func (s *apiServer) byPath(w http.ResponseWriter, r *http.Request, render func(template.ScaffoldEntry, map[string]string) any) {
	want := strings.Trim(r.PathValue("path"), "/")
	// An integration at the workspace root has the identifier "." (see
	// relPath), but a browser strips the "." segment from /api/integrations/.
	// so it arrives empty — treat the two as the same request.
	if want == "" {
		want = "."
	}
	entries, systems := s.scan()
	for _, e := range entries {
		if s.relPath(e.Path) == want {
			writeJSON(w, http.StatusOK, render(e, systems))
			return
		}
	}
	writeError(w, http.StatusNotFound, "integration not found: "+want)
}

// cachedDeployState returns one integration's deployment state — computed on
// first use or when force is set, reused otherwise.
//
// The mutex is held across the provider call rather than only around the map,
// because the command takes an exclusive lock on the shared GitOps checkout:
// two requests running it at once would have one of them fail on the other's
// lock. Serialising here turns that failure into a wait, and concurrent requests
// for the same integration share one run — the same bargain cachedTopologies
// makes with topoMu.
func (s *apiServer) cachedDeployState(ctx context.Context, sum integrationSummary, force bool) deployState {
	s.depMu.Lock()
	defer s.depMu.Unlock()

	if state, ok := s.depStates[sum.Path]; ok && !force {
		return state
	}

	ctx, cancel := context.WithTimeout(ctx, deployStateTimeout)
	defer cancel()
	state := s.dep(ctx, sum)

	if s.depStates == nil {
		s.depStates = map[string]deployState{}
	}
	s.depStates[sum.Path] = state
	return state
}

// enrich reads optional on-disk context for an integration. The entry's Path
// is already usable from the process working directory (see ListScaffolds), so
// it doubles as the project directory.
func (s *apiServer) enrich(e template.ScaffoldEntry, systems map[string]string) integrationDetail {
	dir := e.Path
	return integrationDetail{
		integrationSummary: s.summarize(e, systems),
		Agents:             readDoc(dir, "AGENTS.md"),
		Readme:             readDoc(dir, "README.md"),
		Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
		PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
	}
}

// readDoc returns the named text file's (possibly truncated) contents, or nil
// if it is absent or unreadable.
func readDoc(dir, name string) *fileDoc {
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		return nil
	}
	if len(data) > maxDocBytes {
		data = data[:maxDocBytes]
	}
	return &fileDoc{Name: name, Content: string(data)}
}

// listNames returns the sorted base names of the files directly under dir, or
// nil if dir is absent or unreadable.
func listNames(dir string) []string {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var names []string
	for _, ent := range ents {
		if !ent.IsDir() {
			names = append(names, ent.Name())
		}
	}
	sort.Strings(names)
	return names
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	_ = enc.Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// templatesProvider is the request-independent source for the template
// endpoints: the library release list, show and create all fetch and render
// against. Resolving it once per server keeps the release the form was filled
// against and the release the run renders from the same — a latest-release
// lookup per request could drift between the two.
type templatesProvider struct {
	version   string
	userAgent string

	// Test overrides; production leaves these zero-valued and gets the
	// official library.
	owner         string
	repo          string
	githubBaseURL string
}

// fetchLibrary resolves and downloads the provider's library release. The
// caller owns the returned Library and must Close it.
func (p templatesProvider) fetchLibrary(ctx context.Context) (*template.Library, error) {
	return template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       p.version,
		UserAgent:     p.userAgent,
		Owner:         p.owner,
		Repo:          p.repo,
		GitHubBaseURL: p.githubBaseURL,
	})
}

// createRequest is the POST /api/templates/{name}/create body.
type createRequest struct {
	// Name picks the output directory under the workspace root — the CLI's
	// --out-dir. It is deliberately decoupled from values.name, the schema
	// parameter: a template can want a PascalCase project name next to a
	// kebab-case directory, and the CLI separates the two the same way
	// (--set name=X --out-dir y). Required.
	Name string `json:"name"`

	// Dir is the root-relative, slash-separated directory the output renders
	// under; "" or "." is the workspace root — the pre-Dir behavior. It must
	// already exist: the endpoint scaffolds into systems, it does not invent
	// directory trees.
	Dir string `json:"dir,omitempty"`

	// Values are the template parameters, as --set would supply them.
	Values map[string]any `json:"values"`

	// Force allows rendering into a non-empty output directory.
	Force bool `json:"force,omitempty"`
}

// createResponse is the 201 payload: CreateResult with the output directory
// made root-relative, matching the identifier space /api/integrations uses.
type createResponse struct {
	*template.CreateResult
	// Diagnostics is what the render wrote to stderr, one entry per line —
	// the fetch notice and each dependency render. Provenance, not failure.
	Diagnostics []string `json:"diagnostics,omitempty"`
}

// maxCreateBodyBytes caps a create request body. Parameter values are short
// scalars; a megabyte is already generous and keeps a malformed client from
// streaming unbounded input into memory.
const maxCreateBodyBytes = 1 << 20

// templateSummary is one list entry with the manifest metadata the create
// surfaces filter on — notably the intropy.dev/* labels a flow-view slot
// selects templates by. Additive beside the bare names `templates` keeps.
type templateSummary struct {
	Name        string            `json:"name"`
	Title       string            `json:"title,omitempty"`
	Description string            `json:"description,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
}

// listTemplates mirrors `template list -o json` against the server's library
// release, adding per-template metadata (`entries`) on top of the names. The
// describes are local reads on the already-extracted tarball; one malformed
// manifest drops that entry rather than hiding the rest of the library.
func (s *apiServer) listTemplates(w http.ResponseWriter, r *http.Request) {
	lib, err := s.templates.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	names, err := lib.List()
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	entries := make([]templateSummary, 0, len(names))
	for _, name := range names {
		desc, err := lib.Describe(name)
		if err != nil {
			continue
		}
		entries = append(entries, templateSummary{
			Name:        name,
			Title:       desc.Title,
			Description: desc.Description,
			Labels:      desc.Labels,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"owner":     lib.Owner,
		"repo":      lib.Repo,
		"version":   lib.Version,
		"templates": names,
		"entries":   entries,
	})
}

// getTemplate mirrors `template show -o json` for one template, adding the
// ordered field list the form renders from.
func (s *apiServer) getTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	lib, err := s.templates.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	result, err := lib.Describe(name)
	if err != nil {
		writeError(w, templateFetchStatus(err), err.Error())
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// createTemplate runs `int create` for one template: the form's values
// resolve non-interactively (a missing required parameter is a 422 naming
// it), the skeleton renders under the workspace root, and the result comes
// back as served. Runs are serialized: two concurrent renders of the same
// name would race on the output directory.
func (s *apiServer) createTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	var req createRequest
	dec := json.NewDecoder(io.LimitReader(r.Body, maxCreateBodyBytes))
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: "+err.Error())
		return
	}

	outputDir, values, err := s.resolveCreate(req)
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	s.createMu.Lock()
	defer s.createMu.Unlock()

	prep, err := template.PrepareCreate(r.Context(), template.CreateOptions{
		Template:      name,
		Version:       s.templates.version,
		SetValues:     values,
		UserAgent:     s.templates.userAgent,
		Owner:         s.templates.owner,
		Repo:          s.templates.repo,
		GitHubBaseURL: s.templates.githubBaseURL,
	})
	if err != nil {
		writeError(w, createErrorStatus(err), err.Error())
		return
	}
	defer prep.Cleanup()

	var logs bytes.Buffer
	result, err := template.RunCreate(prep, outputDir, req.Force, &logs)
	if err != nil {
		writeError(w, createErrorStatus(err), err.Error())
		return
	}
	result.OutputDir = s.relPath(result.OutputDir)
	writeJSON(w, http.StatusCreated, createResponse{
		CreateResult: result,
		Diagnostics:  diagnosticLines(logs.String()),
	})
}

// resolveCreate folds the request into the output directory and value set
// `int create --name` would produce: name doubles as values.name and as the
// output directory under dir (the workspace root when dir is empty), confined
// there so the endpoint can never write outside the tree the dashboard serves.
func (s *apiServer) resolveCreate(req createRequest) (string, map[string]any, error) {
	if req.Name == "" {
		return "", nil, errors.New("name is required")
	}
	if strings.ContainsAny(req.Name, `/\`) || req.Name == "." || req.Name == ".." {
		return "", nil, fmt.Errorf("invalid name %q (must be a single path segment)", req.Name)
	}
	segments, err := splitCreateDir(req.Dir)
	if err != nil {
		return "", nil, err
	}

	values := req.Values
	if values == nil {
		values = map[string]any{}
	}
	// A template that does not declare `name` still gets the directory as
	// values.name — the CLI's --name sugar. When the template does declare
	// it, the form's value wins; the two are separate concerns.
	if _, ok := values["name"]; !ok {
		values["name"] = req.Name
	}
	for key := range values {
		if isReservedValueKey(key) {
			return "", nil, fmt.Errorf("value %q is reserved and cannot be supplied", key)
		}
	}

	rootAbs, err := filepath.Abs(s.root)
	if err != nil {
		return "", nil, err
	}
	parentDir := filepath.Join(append([]string{s.root}, segments...)...)
	if len(segments) > 0 {
		// The dir must already exist: creating into a system means the system
		// directory is there; anything else is a client mistake, not a mkdir.
		if info, statErr := os.Stat(parentDir); statErr != nil || !info.IsDir() {
			return "", nil, fmt.Errorf("directory %q does not exist under the workspace root", req.Dir)
		}
	}
	outputDir := filepath.Join(parentDir, req.Name)
	outAbs, err := filepath.Abs(outputDir)
	if err != nil {
		return "", nil, err
	}
	want := filepath.Join(append(append([]string{rootAbs}, segments...), req.Name)...)
	if outAbs != want {
		return "", nil, fmt.Errorf("invalid name %q (output would escape the workspace root)", req.Name)
	}
	return outputDir, values, nil
}

// splitCreateDir validates a create request's dir and returns its segments.
// "" and "." mean the workspace root (no segments). Each segment must be a
// plain directory name — no separators besides "/", no dot entries, nothing
// hidden — so the joined path can only descend from the root.
func splitCreateDir(dir string) ([]string, error) {
	if dir == "" || dir == "." {
		return nil, nil
	}
	if strings.Contains(dir, `\`) {
		return nil, fmt.Errorf("invalid dir %q (must be slash-separated)", dir)
	}
	segments := strings.Split(dir, "/")
	for _, seg := range segments {
		if seg == "" || seg == ".." || strings.HasPrefix(seg, ".") {
			return nil, fmt.Errorf("invalid dir %q (each segment must be a plain directory name)", dir)
		}
	}
	return segments, nil
}

// isReservedValueKey reports whether key is one of the reserved value keys a
// caller injects after resolution (topology, component, …). Users never
// supply them — a form value under one would collide with InjectReserved's
// refusal, so the endpoint refuses first with a message that says why.
func isReservedValueKey(key string) bool {
	switch key {
	case template.ReservedTopologyKey,
		template.ReservedComponentKey,
		template.ReservedGitopsKey,
		template.ReservedScaffoldKey,
		template.ReservedEnvKey:
		return true
	}
	return false
}

// templateFetchStatus maps a library fetch failure to the status the client
// can act on: an unknown template is a 404, anything upstream is a 502.
func templateFetchStatus(err error) int {
	if strings.Contains(err.Error(), "not found in") {
		return http.StatusNotFound
	}
	return http.StatusBadGateway
}

// createErrorStatus maps a create failure to the status the form renders:
// unmet parameters and name conflicts are 422 (the form highlights fields),
// a non-empty output directory is 409 (the form offers force), and a fetch
// failure is 502. Everything else is a plain 500.
func createErrorStatus(err error) int {
	msg := err.Error()
	switch {
	case strings.Contains(msg, "not empty"):
		return http.StatusConflict
	case strings.Contains(msg, "missing required parameter"),
		strings.Contains(msg, "unknown parameter"),
		strings.Contains(msg, "not found in"):
		return http.StatusUnprocessableEntity
	case strings.Contains(msg, "fetch"), strings.Contains(msg, "download"):
		return http.StatusBadGateway
	}
	return http.StatusInternalServerError
}

package topology

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"strings"
	"time"
)

// GraphTimeout bounds one host's graph verb. It is generous because the first
// `dotnet run` restores and builds the project before the verb executes.
const GraphTimeout = 5 * time.Minute

// stderrTailBytes bounds how much of a failing host's output is echoed into the
// error message.
const stderrTailBytes = 2048

// RunGraph executes one system host's graph verb and decodes its stdout.
//
// It builds first and then runs with --no-build --no-launch-profile — the
// invocation the topology library documents — because a plain `dotnet run`
// writes build and launch-profile messages to stdout, corrupting the JSON.
//
// Callers should say what they are doing before calling: on a cold project this
// can take minutes, and a silent wait that long reads as a hang.
func RunGraph(ctx context.Context, hostDir string) (*Topology, error) {
	ctx, cancel := context.WithTimeout(ctx, GraphTimeout)
	defer cancel()

	build := exec.CommandContext(ctx, "dotnet", "build", hostDir, "-v", "q")
	var buildOut bytes.Buffer
	build.Stdout, build.Stderr = &buildOut, &buildOut
	if err := build.Run(); err != nil {
		return nil, fmt.Errorf("build failed: %v%s", err, tail(buildOut.Bytes()))
	}

	cmd := exec.CommandContext(ctx, "dotnet", "run", "--no-build", "--no-launch-profile", "--project", hostDir, "--", "graph")
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("graph verb failed: %v%s", err, tail(stderr.Bytes()))
	}
	t, err := Decode(&stdout)
	if err != nil {
		// The stdout tail, not stderr: a decode failure means the verb printed
		// something other than the record, and that something is the evidence.
		return nil, fmt.Errorf("%w%s", err, tail(stdout.Bytes()))
	}
	return t, nil
}

// tail formats the last stderrTailBytes of a command stream for inclusion in an
// error message, or nothing when the stream is empty.
func tail(b []byte) string {
	s := strings.TrimSpace(string(b))
	if s == "" {
		return ""
	}
	if len(s) > stderrTailBytes {
		s = "…" + s[len(s)-stderrTailBytes:]
	}
	return ": " + s
}

import type { ReactNode } from 'react'
import type {
  Contract,
  JsonSchema,
  MessageDoc,
  Topology,
  TopologyPort,
  TopologyTopic,
} from '../api'
import {
  CategoryIcon,
  CloudIcon,
  DescriptionIcon,
  HubIcon,
  TuneIcon,
} from '../icons'
import { Meta, Section } from './chrome'

/** What the flow canvas has put under inspection: a pub/sub topic (internal
 *  message) or a port (external message). */
export type FlowSelection =
  | { kind: 'topic'; pubsub: string; topic: string }
  | { kind: 'port'; name: string }

interface Props {
  selection: FlowSelection
  topology: Topology
  onClose: () => void
}

/** FlowDetail is the flow view's inspector: what message flows here, and what
 *  does it look like. Topics render their contract's field tree (when the
 *  host published a schema); ports render the authored message doc from
 *  messages/<port>.md (when one exists). */
export function FlowDetail({ selection, topology, onClose }: Props) {
  return (
    <aside className="flow-detail">
      <div className="flow-detail-head">
        <span className="flow-detail-title">
          {selection.kind === 'topic' ? selection.topic : selection.name}
        </span>
        <button
          type="button"
          className="flow-detail-close"
          onClick={onClose}
          aria-label="Close details"
        >
          ×
        </button>
      </div>
      {selection.kind === 'topic' ? (
        <TopicDetail selection={selection} topology={topology} />
      ) : (
        <PortDetail name={selection.name} topology={topology} />
      )}
    </aside>
  )
}

function TopicDetail({
  selection,
  topology,
}: {
  selection: Extract<FlowSelection, { kind: 'topic' }>
  topology: Topology
}) {
  const topic: TopologyTopic | undefined = topology.topics?.find(
    (t) => t.pubsub === selection.pubsub && t.topic === selection.topic,
  )
  const contract: Contract | undefined = topic?.contract
    ? topology.contracts?.find((c) => c.name === topic.contract)
    : undefined

  return (
    <>
      <div className="meta-grid">
        <Meta label="Topic" value={selection.topic} />
        <Meta label="Pubsub" value={selection.pubsub} />
      </div>

      {(topic?.publishers?.length || topic?.subscribers?.length) ? (
        <Section title="Flow" icon={HubIcon}>
          <NameChips label="Publishers" names={topic?.publishers} />
          <NameChips label="Subscribers" names={topic?.subscribers} />
        </Section>
      ) : null}

      <Section title="Contract" icon={CategoryIcon}>
        {!topic?.contract ? (
          <p className="muted">This topic declares no contract.</p>
        ) : (
          <>
            <p className="flow-detail-contract" title={topic.contract}>
              {contract?.shortName ?? topic.contract}
            </p>
            {contract?.schema ? (
              <SchemaTree schema={contract.schema} />
            ) : (
              <p className="muted">
                No schema published by this host — rebuild it with an
                intropy-topology release that emits the contract registry to
                see the contract's fields here.
              </p>
            )}
            {contract?.fingerprint && (
              <p className="flow-detail-fingerprint" title="Schema fingerprint">
                {contract.fingerprint}
              </p>
            )}
          </>
        )}
      </Section>
    </>
  )
}

/** SchemaTree renders a contract's JSON Schema as the field tree a developer
 *  actually asks for: name, type, hierarchy, required. Constructs it does not
 *  recognize degrade to a plain type label — never an error. Exported for the
 *  catalog's contract detail, which renders the same tree. */
export function SchemaTree({ schema }: { schema: JsonSchema }) {
  const defs = schema.$defs ?? {}
  const rows: ReactNode[] = []

  const walk = (s: JsonSchema, depth: number, seen: Set<string>): void => {
    const target = resolve(s, defs, seen)
    if (!target?.properties) return
    const required = new Set(target.required ?? [])
    for (const [name, prop] of Object.entries(target.properties)) {
      rows.push(
        <tr key={`${depth}:${name}:${rows.length}`}>
          <td className="schema-name" style={{ paddingLeft: 8 + depth * 18 }}>
            {name}
          </td>
          <td className="schema-type">{typeLabel(prop, defs)}</td>
          <td className="schema-req">
            {required.has(name) && <span className="badge-required">required</span>}
          </td>
        </tr>,
      )
      const ref = refTarget(prop)
      if (ref && seen.has(ref)) continue
      walk(prop, depth + 1, ref ? new Set(seen).add(ref) : seen)
    }
  }
  walk(schema, 0, new Set())

  if (rows.length === 0) {
    return <p className="muted">The schema declares no fields.</p>
  }
  return (
    <table className="schema-tree">
      <tbody>{rows}</tbody>
    </table>
  )
}

// refTarget names the $def a schema (or the items of an array) points at, or
// undefined for inline shapes — used to cut recursive contracts short.
function refTarget(s: JsonSchema): string | undefined {
  if (s.$ref) return defName(s.$ref)
  if (s.type === 'array' && s.items) return refTarget(s.items)
  return undefined
}

// resolve follows a schema to the object whose properties should nest under
// it: through $ref into $defs and through array items.
function resolve(
  s: JsonSchema | undefined,
  defs: Record<string, JsonSchema>,
  seen: Set<string>,
): JsonSchema | undefined {
  if (!s) return undefined
  if (s.$ref) {
    const def = defs[defName(s.$ref)]
    return def === s ? undefined : def
  }
  if (s.type === 'array') return resolve(s.items, defs, seen)
  return s
}

function defName(ref: string): string {
  return ref.slice(ref.lastIndexOf('/') + 1)
}

// typeLabel is the human-facing type column: nullability folded in ("string"
// from ["string","null"]), arrays suffixed, refs by definition name, and
// anything unrecognized shown as-is rather than hidden.
function typeLabel(s: JsonSchema | undefined, defs: Record<string, JsonSchema>): string {
  if (!s) return 'unknown'
  if (s.$ref) return defName(s.$ref)
  if (s.enum) return 'enum'
  if (Array.isArray(s.type)) {
    const types = s.type.filter((t) => t !== 'null')
    const label = types.map((t) => labelFor(t, s, defs)).join(' | ')
    return label || 'null'
  }
  return labelFor(s.type, s, defs)
}

function labelFor(
  type: string | undefined,
  s: JsonSchema,
  defs: Record<string, JsonSchema>,
): string {
  if (type === 'array') return `${typeLabel(s.items, defs)}[]`
  if (type === 'string' && s.format) return s.format
  return type ?? 'unknown'
}

function PortDetail({ name, topology }: { name: string; topology: Topology }) {
  const port: TopologyPort | undefined = topology.ports?.find(
    (c) => c.name === name,
  )
  const doc: MessageDoc | undefined = topology.messageDocs?.[name]

  return (
    <>
      <div className="meta-grid">
        <Meta label="Port" value={name} />
        {port?.externalSystem && (
          <Meta label="External system" value={port.externalSystem} />
        )}
        {port?.directions?.length ? (
          <Meta label="Direction" value={port.directions.join(', ')} />
        ) : null}
      </div>

      <NameChips label="Used by" names={port?.usedBy} />

      {doc ? <MessageDocView doc={doc} /> : <MessageDocEmpty topology={topology} name={name} />}
    </>
  )
}

/** MessageDocView renders an authored payload description: the structured
 *  facts, the column table, the prose, and the (author-redacted) sample. */
function MessageDocView({ doc }: { doc: MessageDoc }) {
  const facts: Array<[string, string | undefined]> = [
    ['Format', doc.format],
    ['Delimiter', doc.delimiter],
    ['Encoding', doc.encoding],
    ['File pattern', doc.filePattern],
    ['Frequency', doc.frequency],
    ['Contact', doc.contact],
  ]
  const present = facts.filter((f): f is [string, string] => Boolean(f[1]))

  return (
    <>
      <Section title="Message" icon={TuneIcon}>
        {doc.lastReviewed && <ReviewedBadge date={doc.lastReviewed} />}
        {present.length > 0 ? (
          <table className="kv">
            <tbody>
              {present.map(([k, v]) => (
                <tr key={k}>
                  <th>{k}</th>
                  <td>{v}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p className="muted">No structured facts recorded.</p>
        )}
      </Section>

      {doc.fields && doc.fields.length > 0 && (
        <Section title="Fields" icon={CategoryIcon}>
          <table className="schema-tree">
            <tbody>
              {doc.fields.map((f, i) => (
                <tr key={`${f.name}:${i}`}>
                  <td className="schema-name">
                    {f.position ? `${f.position}. ` : ''}
                    {f.name}
                  </td>
                  <td className="schema-type">{f.type ?? ''}</td>
                  <td className="schema-req">
                    {f.required && <span className="badge-required">required</span>}
                  </td>
                  <td className="schema-notes">{f.notes ?? ''}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Section>
      )}

      {doc.body && (
        <Section title="Notes" icon={DescriptionIcon}>
          <pre className="doc">{doc.body}</pre>
        </Section>
      )}

      {doc.sample?.inline && (
        <Section title="Sample" icon={CloudIcon}>
          <pre className="doc">{doc.sample.inline}</pre>
        </Section>
      )}
    </>
  )
}

/** The empty state doubles as the authoring onboarding: where to put the file
 *  and what to write in it. */
function MessageDocEmpty({ topology, name }: { topology: Topology; name: string }) {
  const dir = topology.path === '.' ? '' : `${topology.path}/`
  const today = new Date().toISOString().slice(0, 10)
  const template = `---
format: csv
delimiter: ";"
encoding: utf-8
filePattern: "*.csv"
frequency: describe when it arrives
fields:
  - name: FIELD_NAME
    type: string
    notes: what this column carries
sample:
  inline: "one;example;line"
  redacted: true
contact: who owns the source system
lastReviewed: ${today}
---
Free prose: where the data comes from, quirks, dedupe keys, gotchas.
`
  return (
    <Section title="Message" icon={DescriptionIcon}>
      <p className="muted">
        No message description yet. Describe what flows through this port
        in <code>{dir}messages/{name}.md</code>:
      </p>
      <pre className="doc">{template}</pre>
    </Section>
  )
}

// ReviewedBadge is the staleness story of an authored doc: it renders how
// long ago the author last vouched for it.
function ReviewedBadge({ date }: { date: string }) {
  const parsed = Date.parse(date)
  let ago = ''
  if (!Number.isNaN(parsed)) {
    const days = Math.floor((Date.now() - parsed) / 86_400_000)
    if (days >= 0) {
      if (days < 1) ago = 'today'
      else if (days < 61) ago = `${days} day${days === 1 ? '' : 's'} ago`
      else ago = `${Math.floor(days / 30.44)} months ago`
    }
  }
  return (
    <p className="flow-detail-reviewed" title={date}>
      reviewed {ago || date}
    </p>
  )
}

function NameChips({ label, names }: { label: string; names?: string[] }) {
  if (!names?.length) return null
  return (
    <div className="flow-detail-chips">
      <span className="meta-label">{label}</span>
      <ul className="chips">
        {names.map((n) => (
          <li key={n} className="chip">
            {n}
          </li>
        ))}
      </ul>
    </div>
  )
}

