// Declared extractors offer seeding. Ghosts identified as extractors carry
// the disabled variant; ghosts of unknown kind get nothing — the data
// model cannot always tell "known extractor, undeclared" from "unknown
// kind", so it errs on absence rather than a misleading disabled button.
const seedable = useMemo(() => {
  const ready = new Set<string>()
  for (const c of effective?.components ?? []) {
    if (dataFlowFor(c.kind) === 'in') ready.add(c.name)
  }
  const ghost = new Set<string>()
  for (const g of builtGhosts(effective, items)) {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    if (flow === 'in') ghost.add(g.path)
  }
  return { ready, ghost }
}, [effective, items])

const built = useMemo(
  () =>
    effective
      ? buildDeclaredGraph(effective, items)
      : { nodes: [] as Node[], edges: [] as Edge[], ghosts: [] as IntegrationDetail[] },
  [effective, items],
)
const seededNodes = useMemo(
  () =>
    built.nodes.map((n) => {
      if (n.type !== 'integration') return n
      const d = n.data as IntNodeData
      const seed = d.ghost
        ? seedable.ghost.has(n.id)
          ? ('ghost' as const)
          : undefined
        : seedable.ready.has(d.name)
          ? ('ready' as const)
          : undefined
      return seed === d.seed ? n : { ...n, data: { ...d, seed } }
    }),
  [built, seedable],
)
useEffect(() => setNodes(seededNodes), [seededNodes, setNodes])

