// systemHostDir locates the system-host project directory under sysDir —
// the anchor every development rootPath is declared against. The host is
// rediscovered on each seed, the same freshness rule resolveRun applies to
// start/stop: a sys update between refreshes must not strand the lookup.
func systemHostDir(sysDir string) (string, error) {
	hosts, err := template.ListSystemHosts(sysDir)
	if err != nil || len(hosts) == 0 {
		return "", fmt.Errorf("no system host under %s — create one with the system's host sync or 'intropy sys create'", sysDir)
	}
	return hosts[0].Path, nil
}

// displayDir expresses hostDir as root-joined (non-canonicalized) path: the
// form relPath turns into a clean API identifier. hostDir is always inside
// sysDir (the host scaffold lives under the system), so the re-join cannot
// escape.
func displayDir(root, sysDir, hostDir string) (string, error) {
	rel, err := filepath.Rel(sysDir, hostDir)
	if err != nil {
		return "", err
	}
	segments, err := splitCreateDir(filepath.ToSlash(rel))
	if err != nil {
		return "", fmt.Errorf("host directory %q escapes its system directory", hostDir)
	}
	rootAbs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	sysAbs, err := filepath.Abs(sysDir)
	if err != nil {
		return "", err
	}
	sysRel, err := filepath.Rel(rootAbs, sysAbs)
	if err != nil {
		return "", err
	}
	parts := append([]string{root}, filepath.SplitList(sysRel)...)
	_ = parts
	return filepath.Join(append([]string{root}, append(filepath.SplitList(sysRel), segments...)...)...), nil
}

